// Extract invoice file, prompt, and user config from request
const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body || item.json;

  // Get the PDF file (base64 encoded)
  const fileData = body.file || body.document || body.pdf_base64;
  if (!fileData) {
    throw new Error('No invoice file provided. Send as "file" in base64 format.');
  }

  // Get the extraction prompt
  const prompt = body.prompt;
  if (!prompt) {
    throw new Error('No extraction prompt provided. Send "prompt" field with AI instructions.');
  }

  // Get metadata
  const filename = body.filename || 'invoice.pdf';
  const userEmail = body.user_email || null;

  // Get user's expected banking details (from their business profile)
  const expectedBanking = body.expected_banking || null;

  // Convert base64 to buffer
  let buffer;
  if (typeof fileData === 'string') {
    buffer = Buffer.from(fileData, 'base64');
  } else if (fileData.data) {
    buffer = Buffer.from(fileData.data, 'base64');
  } else {
    throw new Error('Invalid file format. Provide base64 string.');
  }

  results.push({
    json: {
      prompt: prompt,
      filename: filename,
      user_email: userEmail,
      expected_banking: expectedBanking,
      received_at: new Date().toISOString()
    },
    binary: {
      data: {
        data: buffer.toString('base64'),
        mimeType: 'application/pdf',
        fileName: filename
      }
    }
  });
}

return results;

/**
 * PennyPilot Guardrails & SARS Compliance Validation
 * 
 * Security Checks:
 * 1. Parse Gemini JSON response safely
 * 2. Validate sum(line_items) == subtotal
 * 3. Validate VAT calculation (15%)
 * 4. Convert SA currency format (R 10,00) to float (10.00)
 * 5. SARS compliance flags for invoices > R5000
 * 6. Banking details verification (user-specific)
 */

// Get user's expected banking from payload (passed from frontend/database)
const inputMetadata = $('2. Extract File & Prompt').item.json;
const EXPECTED_BANK = inputMetadata.expected_banking || null;

const SA_VAT_RATE = 0.15;
const SARS_VAT_THRESHOLD = 5000;

// Get Gemini response
const geminiResponse = $input.first().json;
let rawText;

// Handle various Gemini response formats
if (geminiResponse.parts && geminiResponse.parts[0] && geminiResponse.parts[0].text) {
  rawText = geminiResponse.parts[0].text;
} else if (geminiResponse.content && geminiResponse.content.parts && geminiResponse.content.parts[0]) {
  rawText = geminiResponse.content.parts[0].text;
} else if (geminiResponse.text) {
  rawText = geminiResponse.text;
} else if (geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text) {
  rawText = geminiResponse.candidates[0].content.parts[0].text;
} else if (geminiResponse.content?.[0]?.text) {
  rawText = geminiResponse.content[0].text;
} else {
  return {
    json: {
      success: false,
      error: 'GEMINI_RESPONSE_ERROR',
      error_message: 'Could not parse Gemini response structure',
      raw_response: JSON.stringify(geminiResponse).substring(0, 500)
    }
  };
}

// Clean markdown if present
rawText = String(rawText).trim()
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .replace(/^\s*```\s*/g, '')
  .replace(/\s*```\s*$/g, '');

let extracted;
try {
  extracted = JSON.parse(rawText);
} catch (e) {
  return {
    json: {
      success: false,
      error: 'JSON_PARSE_ERROR',
      error_message: 'Failed to parse Gemini response as JSON',
      raw_response: rawText.substring(0, 500)
    }
  };
}

// === Currency Conversion ===
function parseAmount(value) {
  if (typeof value === 'number') return value;
  if (!value) return 0;

  let cleaned = String(value);
  cleaned = cleaned.replace(/[R\s]/g, '');

  // Handle SA format: 15 000,00
  if (/^[\d\s]+,\d{2}$/.test(cleaned)) {
    cleaned = cleaned.replace(/\s/g, '').replace(',', '.');
  }

  // Handle US format: 15,000.00
  if (/^\d{1,3}(,\d{3})*(\.\d{2})?$/.test(cleaned)) {
    cleaned = cleaned.replace(/,/g, '');
  }

  return parseFloat(cleaned) || 0;
}

// === Parse Invoice ===
const invoice = {
  invoice_number: extracted.invoice_number || null,
  invoice_date: extracted.invoice_date || null,
  due_date: extracted.due_date || null,
  client_name: extracted.client_name || null,
  client_email: extracted.client_email || null,
  subtotal: parseAmount(extracted.subtotal),
  vat_rate: parseFloat(extracted.vat_rate) || 15,
  vat_amount: parseAmount(extracted.vat_amount),
  amount: parseAmount(extracted.amount || extracted.total),
  description: extracted.description || null,
  items: [],
  supplier_details: extracted.supplier_details || null,
  recipient_details: extracted.recipient_details || null,
  banking: extracted.banking || null,
  compliance: extracted.compliance || null,
  confidence: extracted.confidence || 0
};

// === Parse Line Items ===
let lineItemsTotal = 0;
if (Array.isArray(extracted.items) || Array.isArray(extracted.line_items)) {
  const items = extracted.items || extracted.line_items || [];
  invoice.items = items.map((item, idx) => {
    const qty = parseFloat(item.quantity) || 1;
    const unitPrice = parseAmount(item.unit_price);
    const amount = parseAmount(item.amount) || (qty * unitPrice);
    lineItemsTotal += amount;

    return {
      description: item.description || `Line item ${idx + 1}`,
      quantity: qty,
      unit_price: unitPrice,
      amount: amount
    };
  });
}

// === VALIDATION CHECKS ===
const validationErrors = [];
const tolerance = 0.50; // 50 cents tolerance for rounding

// Check 1: Line items sum matches subtotal
if (invoice.items.length > 0 && invoice.subtotal > 0) {
  const diff = Math.abs(lineItemsTotal - invoice.subtotal);
  if (diff > tolerance) {
    validationErrors.push({
      check: 'LINE_ITEMS_SUM',
      message: `Line items total (R${lineItemsTotal.toFixed(2)}) does not match subtotal (R${invoice.subtotal.toFixed(2)})`,
      expected: invoice.subtotal,
      actual: lineItemsTotal,
      difference: diff
    });
  }
}

// Check 2: VAT calculation
if (invoice.subtotal > 0 && invoice.vat_amount > 0) {
  const expectedVat = invoice.subtotal * SA_VAT_RATE;
  const vatDiff = Math.abs(expectedVat - invoice.vat_amount);
  if (vatDiff > tolerance) {
    validationErrors.push({
      check: 'VAT_CALCULATION',
      message: `VAT amount (R${invoice.vat_amount.toFixed(2)}) does not match 15% of subtotal (R${expectedVat.toFixed(2)})`,
      expected: expectedVat,
      actual: invoice.vat_amount,
      difference: vatDiff
    });
  }
}

// Check 3: Total = Subtotal + VAT
if (invoice.subtotal > 0 && invoice.amount > 0) {
  const expectedTotal = invoice.subtotal + invoice.vat_amount;
  const totalDiff = Math.abs(expectedTotal - invoice.amount);
  if (totalDiff > tolerance) {
    validationErrors.push({
      check: 'TOTAL_CALCULATION',
      message: `Total (R${invoice.amount.toFixed(2)}) does not match subtotal + VAT (R${expectedTotal.toFixed(2)})`,
      expected: expectedTotal,
      actual: invoice.amount,
      difference: totalDiff
    });
  }
}

// Check 4: SARS compliance for invoices > R5000
const sarsCompliance = {
  amount_exceeds_threshold: invoice.amount > SARS_VAT_THRESHOLD,
  requires_recipient_vat: invoice.amount > SARS_VAT_THRESHOLD,
  has_recipient_vat: !!(invoice.recipient_details?.vat_number),
  has_supplier_vat: !!(invoice.supplier_details?.vat_number),
  is_compliant: true
};

if (sarsCompliance.requires_recipient_vat && !sarsCompliance.has_recipient_vat) {
  sarsCompliance.is_compliant = false;
  validationErrors.push({
    check: 'SARS_RECIPIENT_VAT',
    message: `Invoice > R5000 requires recipient VAT number per SARS regulations`,
    amount: invoice.amount,
    threshold: SARS_VAT_THRESHOLD
  });
}

// === Banking Match ===
const bankingMatch = {
  is_match: false,
  skipped: !EXPECTED_BANK,
  expected: EXPECTED_BANK,
  extracted: {
    bank_name: invoice.banking?.bank || null,
    account_number: invoice.banking?.account || null
  }
};

// Only verify if expected banking was provided
if (EXPECTED_BANK && EXPECTED_BANK.account_number && bankingMatch.extracted.account_number) {
  const normalizedExtracted = String(bankingMatch.extracted.account_number).replace(/\D/g, '');
  const normalizedExpected = String(EXPECTED_BANK.account_number).replace(/\D/g, '');
  bankingMatch.is_match = normalizedExtracted === normalizedExpected;
}

// === Determine Status ===
let status = 'validated';
if (validationErrors.length > 0) {
  status = 'pending_review';
}

// === Output ===
return {
  json: {
    success: true,
    data: {
      invoice_number: invoice.invoice_number,
      invoice_date: invoice.invoice_date,
      due_date: invoice.due_date,
      client_name: invoice.client_name,
      client_email: invoice.client_email,
      amount: invoice.amount,
      subtotal: invoice.subtotal,
      vat_rate: invoice.vat_rate,
      vat_amount: invoice.vat_amount,
      description: invoice.description,
      items: invoice.items,
      supplier_details: invoice.supplier_details,
      recipient_details: invoice.recipient_details,
      banking: invoice.banking,
      compliance: invoice.compliance,
      confidence: invoice.confidence
    },
    validation: {
      status: status,
      errors: validationErrors,
      line_items_total: lineItemsTotal
    },
    sars_compliance: sarsCompliance,
    banking_match: bankingMatch,
    metadata: {
      filename: inputMetadata.filename,
      source: 'n8n-gemini-pipeline',
      extracted_at: new Date().toISOString()
    }
  }
};
